const lib = await import("/Users/vacilando/.local/share/alloy/toolkit/current/lib/hosted-fixture-safety.mjs");
const profile = { idPrefix: "fd000000-", ownership: { financial_subsidy_claims: "program_id" }, requireReplicaWindow: false };
const cases = {
  unqualified_scoped: "delete from financial_subsidy_claims where org_id = :'org' and program_id = :'program';",
  qualified_scoped: "delete from public.financial_subsidy_claims where org_id = :'org' and program_id = :'program';",
  qualified_org_wide: "delete from public.financial_subsidy_claims where org_id = :'org';",
  quoted_qualified_org_wide: 'delete from "public"."financial_subsidy_claims" where org_id = :\'org\';',
};
for (const [k, sql] of Object.entries(cases)) {
  const stmts = lib.destructiveStatements(sql).map((d) => d.table);
  const rep = lib.auditHostedFixture(sql, profile);
  const v = lib.hostedFixtureVerdict(rep, profile);
  console.log(JSON.stringify({ case: k, tables: stmts, subsidy_present: rep.subsidy[0].present, org_wide: rep.org_wide, ok: v.ok, failures: v.failures }));
}
// proposed regex, measured on the same inputs (not installed anywhere)
const proposed = (sql) => [...String(sql).matchAll(/delete\s+from\s+(?:only\s+)?(?:"?[a-z_][a-z0-9_]*"?\s*\.\s*)?"?([a-z_][a-z0-9_]*)"?[\s\S]*?;/gi)].map((m) => m[1]);
for (const [k, sql] of Object.entries(cases)) console.log(JSON.stringify({ case: k, proposed_tables: proposed(sql) }));

